import sys

def eventualSafeNodes(V, adj):
    def dfs(node):
        if visited[node] == 1:
            return False
        if visited[node] == 2:
            return True
        visited[node] = 1
        for neighbor in adj[node]:
            if not dfs(neighbor):
                return False
        visited[node] = 2
        return True

    visited = [0] * V
    safe_nodes = []
    for i in range(V):
        if dfs(i):
            safe_nodes.append(i)
    return safe_nodes

def main():
    import sys
    input = sys.stdin.read().split()
    V = int(input[0])
    adj = [[] for _ in range(V)]
    index = 1
    for i in range(V):
        num_edges = int(input[index])
        index += 1
        for _ in range(num_edges):
            adj[i].append(int(input[index]))
            index += 1
    result = eventualSafeNodes(V, adj)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
